        sampling: r.sampling ?? null,
      })),
    });
  };

  // The PDF "export" is the browser's own print-to-PDF: `RunReport` (rendered once, always, in
  // `RunDetail`) is a chrome-free print-only twin of this page.
  const exportPdf = () => window.print();

  return (
    <Dropdown
      menu={{
